//! The locales Intl is built with, and the baked ICU4X data for them.
//!
//! Everything in this crate is generated by `icu/generate_intl_data.sh`, which is also what changes
//! the locale set. The output is checked in so that building the JS engine does not rebuild it. See
//! README.md. The one exception is [`locale_info`], the CLDR rows that no ICU4X data marker covers
//! and that `Intl.Locale` therefore needs written into the engine itself.

mod built_in;
pub mod locale_info;
mod provider;

// The generated `TimezoneNamesEssentialsV1` table spells the owning type of its `Cow` fields as
// `alloc::borrow::Cow`, which every other generated table spells as `std::borrow::Cow`. In a `std`
// crate the `alloc` crate is linked but not in scope by name, so this one line is what a generated
// data crate needs to be able to say either.
extern crate alloc;

pub use built_in::{BUILT_IN_LOCALES, DEFAULT_LOCALE, TIME_ZONE_NAMES_ARE_BAKED};
pub use provider::IntlDataProvider;

/// The default locale must be built in: it is what every locale resolves to when nothing
/// requested is available, so Intl would otherwise report a locale it has no data for. The
/// generator script refuses to run without it; this keeps a hand-edited `built_in.rs` from
/// getting through.
const _: () = assert!(contains(BUILT_IN_LOCALES, DEFAULT_LOCALE));

const fn contains(locales: &[&str], locale: &str) -> bool {
    let mut i = 0;
    while i < locales.len() {
        if equals(locales[i], locale) {
            return true;
        }

        i += 1;
    }

    false
}

const fn equals(a: &str, b: &str) -> bool {
    let a = a.as_bytes();
    let b = b.as_bytes();

    if a.len() != b.len() {
        return false;
    }

    let mut i = 0;
    while i < a.len() {
        if a[i] != b[i] {
            return false;
        }

        i += 1;
    }

    true
}
